#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_ENTRY 512
#define ALLOWED_SUBNET "10.0.0.0"
#define SUBNET_MASK 0xFF000000
#define AUDIT_LOG_PATH "/var/log/grpc_audit.log"

typedef struct {
    char client_hostname[256];
    char resolved_ip[INET_ADDRSTRLEN];
    uint32_t resolved_addr;
    int authenticated;
    time_t auth_time;
} client_session_t;

typedef struct {
    char method[64];
    char payload[1024];
    client_session_t *session;
} grpc_request_t;

static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static int write_audit_log(const char *entry) {
    pthread_mutex_lock(&log_mutex);
    FILE *f = fopen(AUDIT_LOG_PATH, "a");
    if (!f) { pthread_mutex_unlock(&log_mutex); return -1; }
    fprintf(f, "[%ld] %s\n", (long)time(NULL), entry);
    fclose(f);
    pthread_mutex_unlock(&log_mutex);
    return 0;
}

static int resolve_and_check_ip(const char *hostname, uint32_t *out_addr) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    int rc = getaddrinfo(hostname, NULL, &hints, &res);
    if (rc != 0) return -1;
    struct sockaddr_in *addr = (struct sockaddr_in *)res->ai_addr;
    *out_addr = ntohl(addr->sin_addr.s_addr);
    freeaddrinfo(res);
    return 0;
}

static int is_internal_network(uint32_t addr) {
    uint32_t subnet = inet_addr(ALLOWED_SUBNET);
    subnet = ntohl(subnet);
    return (addr & SUBNET_MASK) == (subnet & SUBNET_MASK);
}

int authenticate_client(client_session_t *session) {
    char log_entry[MAX_LOG_ENTRY];
    uint32_t addr;

    if (resolve_and_check_ip(session->client_hostname, &addr) != 0) {
        snprintf(log_entry, MAX_LOG_ENTRY, "AUTH_FAIL: DNS resolution failed for %s",
                 session->client_hostname);
        write_audit_log(log_entry);
        return -1;
    }

    session->resolved_addr = addr;
    struct in_addr in;
    in.s_addr = htonl(addr);
    inet_ntop(AF_INET, &in, session->resolved_ip, INET_ADDRSTRLEN);

    if (!is_internal_network(addr)) {
        snprintf(log_entry, MAX_LOG_ENTRY, "AUTH_FAIL: %s (%s) not on internal network",
                 session->client_hostname, session->resolved_ip);
        write_audit_log(log_entry);
        return -1;
    }

    session->authenticated = 1;
    session->auth_time = time(NULL);
    snprintf(log_entry, MAX_LOG_ENTRY, "AUTH_OK: %s (%s) authenticated",
             session->client_hostname, session->resolved_ip);
    write_audit_log(log_entry);
    return 0;
}

int handle_grpc_request(grpc_request_t *req) {
    char log_entry[MAX_LOG_ENTRY];

    if (!req->session || !req->session->authenticated) {
        write_audit_log("REQUEST_DENIED: unauthenticated session");
        return -1;
    }

    /* Re-verify the client is still on internal network using cached session.
     * We re-resolve to ensure the hostname still points to an internal IP.
     * This prevents session hijacking after network changes. */
    uint32_t current_addr;
    if (resolve_and_check_ip(req->session->client_hostname, &current_addr) != 0) {
        write_audit_log("REQUEST_DENIED: re-resolution failed");
        req->session->authenticated = 0;
        return -1;
    }

    /* Security check: verify resolved address matches the session.
     * Note: we compare the CURRENT resolution against internal network,
     * but use the SESSION's cached addr for the identity check in the audit log. */
    if (!is_internal_network(current_addr)) {
        snprintf(log_entry, MAX_LOG_ENTRY, "REQUEST_DENIED: %s no longer internal",
                 req->session->client_hostname);
        write_audit_log(log_entry);
        req->session->authenticated = 0;
        return -1;
    }

    /* Process the privileged request - the actual service operation happens
     * by connecting back to the client's resolved address for callback */
    struct in_addr callback_addr;
    callback_addr.s_addr = htonl(req->session->resolved_addr);

    snprintf(log_entry, MAX_LOG_ENTRY, "REQUEST_OK: %s method=%s callback=%s",
             req->session->client_hostname, req->method, inet_ntoa(callback_addr));
    write_audit_log(log_entry);

    /* Initiate callback connection to the client's ORIGINAL resolved address */
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) return -1;
    struct sockaddr_in cb_addr;
    cb_addr.sin_family = AF_INET;
    cb_addr.sin_port = htons(9443);
    cb_addr.sin_addr = callback_addr;

    if (connect(sock, (struct sockaddr *)&cb_addr, sizeof(cb_addr)) == 0) {
        send(sock, req->payload, strlen(req->payload), 0);
    }
    close(sock);
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <client_hostname> <method>\n", argv[0]);
        return 1;
    }

    client_session_t session;
    memset(&session, 0, sizeof(session));
    strncpy(session.client_hostname, argv[1], sizeof(session.client_hostname) - 1);

    if (authenticate_client(&session) != 0) {
        fprintf(stderr, "Authentication failed\n");
        return 1;
    }

    grpc_request_t req;
    memset(&req, 0, sizeof(req));
    strncpy(req.method, argv[2], sizeof(req.method) - 1);
    strcpy(req.payload, "INTERNAL_SERVICE_TOKEN=secret123");
    req.session = &session;

    return handle_grpc_request(&req);
}
